public class MainActivity extends Activity {
    static final int BG=0xfff5f7f4, CARD=0xffffffff, TEXT=0xff172e29, MUTED=0xff64756e, GREEN=0xff24745f, PALE=0xffe1efe7, LINE=0xffe4eae5;
    Store store; LinearLayout root, top, page, nav; ScrollView scroll; FrameLayout shell, drawer; ScrollView drawerScroll;
    final Map<String,Bitmap> icons=new HashMap<>(); String selectedSource=null;
    int tab=0; boolean unreadOnly=false, lastRunning=false; long revision=-1; float downY;
    Handler handler=new Handler(Looper.getMainLooper());
    final Runnable poll=new Runnable(){public void run(){boolean r=RefreshJob.running.get();if(store.revision()!=revision||r!=lastRunning){render(true);}handler.postDelayed(this,1200);}};
    @Override public void onCreate(Bundle state){super.onCreate(state);store=new Store(this);RefreshJob.channel(this);RefreshJob.schedule(this,false);getWindow().setStatusBarColor(BG);getWindow().setNavigationBarColor(CARD);getWindow().getDecorView().setSystemUiVisibility(View.SYSTEM_UI_FLAG_LIGHT_STATUS_BAR|View.SYSTEM_UI_FLAG_LIGHT_NAVIGATION_BAR);build();render(false);}
    @Override protected void onResume(){super.onResume();render(true);handler.removeCallbacks(poll);handler.post(poll);}
    @Override protected void onPause(){super.onPause();handler.removeCallbacks(poll);}
    @Override protected void onNewIntent(Intent intent){super.onNewIntent(intent);closeDrawer();selectedSource=null;tab=0;render(false);}
    @Override public void onBackPressed(){if(drawer!=null){closeDrawer();return;}if(tab==0&&selectedSource!=null){selectSource(null);return;}super.onBackPressed();}
    int d(float n){return Math.round(n*getResources().getDisplayMetrics().density);}
    LinearLayout column(){LinearLayout l=new LinearLayout(this);l.setOrientation(LinearLayout.VERTICAL);return l;}
    LinearLayout row(){LinearLayout l=new LinearLayout(this);l.setOrientation(LinearLayout.HORIZONTAL);l.setGravity(Gravity.CENTER_VERTICAL);return l;}
    TextView text(String t,float size,int color,boolean bold){TextView v=new TextView(this);v.setText(t);v.setTextSize(size);v.setTextColor(color);v.setIncludeFontPadding(true);if(bold)v.setTypeface(Typeface.DEFAULT,Typeface.BOLD);return v;}
    GradientDrawable shape(int color,int radius){GradientDrawable g=new GradientDrawable();g.setColor(color);g.setCornerRadius(d(radius));return g;}
    GradientDrawable outline(int color,int radius,int border){GradientDrawable g=shape(color,radius);g.setStroke(d(1),border);return g;}
    void pad(View v,int l,int t,int r,int b){v.setPadding(d(l),d(t),d(r),d(b));}
    void add(LinearLayout parent,View view){parent.addView(view,new LinearLayout.LayoutParams(-1,-2));}
    void gap(LinearLayout p,int dp){View v=new View(this);p.addView(v,new LinearLayout.LayoutParams(-1,d(dp)));}
    void line(LinearLayout p){View v=new View(this);v.setBackgroundColor(LINE);p.addView(v,new LinearLayout.LayoutParams(-1,d(1)));}
    TextView action(String label,boolean primary,Runnable click){TextView v=text(label,14,primary?CARD:GREEN,true);v.setGravity(Gravity.CENTER);pad(v,15,10,15,10);v.setBackground(shape(primary?GREEN:PALE,14));v.setOnClickListener(x->click.run());return v;}
    void build(){shell=new FrameLayout(this);shell.setBackgroundColor(BG);root=column();root.setBackgroundColor(BG);shell.addView(root,new FrameLayout.LayoutParams(-1,-1));setContentView(shell);shell.setOnApplyWindowInsetsListener((v,insets)->{if(Build.VERSION.SDK_INT>=30){android.graphics.Insets i=insets.getInsets(WindowInsets.Type.systemBars());v.setPadding(i.left,i.top,i.right,i.bottom);}else v.setPadding(insets.getSystemWindowInsetLeft(),insets.getSystemWindowInsetTop(),insets.getSystemWindowInsetRight(),insets.getSystemWindowInsetBottom());return insets;});top=column();pad(top,20,13,20,8);add(root,top);scroll=new ScrollView(this);scroll.setFillViewport(true);scroll.setClipToPadding(false);scroll.setVerticalScrollBarEnabled(false);page=column();pad(page,18,9,18,20);scroll.addView(page,new ScrollView.LayoutParams(-1,-2));root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));scroll.setOnTouchListener((v,e)->{if(e.getAction()==MotionEvent.ACTION_DOWN)downY=scroll.getScrollY()==0?e.getY():-10000;if(e.getAction()==MotionEvent.ACTION_UP&&tab==0&&downY>=0&&e.getY()-downY>d(100)){refresh(selectedSource);return true;}return false;});line(root);nav=row();nav.setBackgroundColor(CARD);pad(nav,10,6,10,7);add(root,nav);}
    void render(boolean keep){if(root==null)return;int pos=keep?scroll.getScrollY():0;revision=store.revision();lastRunning=RefreshJob.running.get();top.removeAllViews();page.removeAllViews();nav.removeAllViews();
        Store.Source chosen=sourceById(selectedSource);if(chosen==null)selectedSource=null;
        LinearLayout titleRow=row(), titleBox=column();if(tab==0){TextView menu=action("☰",false,()->showDrawer());menu.setContentDescription("打开网站侧边栏");pad(menu,10,11,10,11);titleRow.addView(menu,new LinearLayout.LayoutParams(d(46),d(46)));View space=new View(this);titleRow.addView(space,new LinearLayout.LayoutParams(d(10),1));}String main=tab==0?(chosen==null?"讯集":chosen.name):tab==1?"订阅":"设置";TextView title=text(main,chosen!=null&&tab==0?21:29,TEXT,true);title.setMaxLines(2);title.setEllipsize(android.text.TextUtils.TruncateAt.END);add(titleBox,title);String sub=tab==0?(chosen==null?"你关注的世界，正在更新。":"当前网站 · 点击左侧切换"):tab==1?"管理你关心的信息来源":"让消息主动找到你";TextView st=text(sub,12,MUTED,false);add(titleBox,st);titleRow.addView(titleBox,new LinearLayout.LayoutParams(0,-2,1));if(tab==0)titleRow.addView(action(lastRunning?"更新中…":"↻  刷新",false,()->refresh(selectedSource)));if(tab==1)titleRow.addView(action("＋  添加",true,()->addSource()));add(top,titleRow);
        if(tab==0)feed();else if(tab==1)sources();else settings();
        String[] labels={"信息流","我的订阅","设置"};String[] glyphs={"▤","◇","⚙"};for(int i=0;i<3;i++){final int target=i;LinearLayout item=column();item.setGravity(Gravity.CENTER);pad(item,2,4,2,4);TextView icon=text(glyphs[i],24,tab==i?GREEN:MUTED,true);icon.setGravity(Gravity.CENTER);add(item,icon);TextView label=text(labels[i],11,tab==i?GREEN:MUTED,tab==i);label.setGravity(Gravity.CENTER);add(item,label);if(tab==i)item.setBackground(shape(PALE,15));item.setOnClickListener(v->{tab=target;render(false);});LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(0,-2,1);lp.setMargins(d(4),0,d(4),0);nav.addView(item,lp);}scroll.post(()->scroll.scrollTo(0,pos));if(drawer!=null)fillDrawer();
    }
    Store.Source sourceById(String id){if(id==null)return null;for(Store.Source s:store.sources())if(id.equals(s.id))return s;return null;}
    View avatar(String id,String name,int size){Bitmap b=icons.get(id);if(b==null&&id!=null){b=SiteIcons.load(this,id);if(b!=null)icons.put(id,b);}if(b!=null){ImageView i=new ImageView(this);i.setImageBitmap(b);i.setScaleType(ImageView.ScaleType.FIT_CENTER);i.setBackground(outline(SiteIcons.needsDarkBackground(b)?GREEN:CARD,10,LINE));i.setClipToOutline(true);pad(i,3,3,3,3);return i;}String initial=name==null||name.isEmpty()?"讯":name.substring(0,name.offsetByCodePoints(0,1));TextView v=text(initial,size,GREEN,true);v.setGravity(Gravity.CENTER);v.setBackground(shape(PALE,10));return v;}
    void selectSource(String id){selectedSource=id;tab=0;unreadOnly=false;feedLimit=60;closeDrawer();render(false);}
    void showDrawer(){if(drawer!=null)return;drawer=new FrameLayout(this);View shade=new View(this);shade.setBackgroundColor(0x660c211b);shade.setOnClickListener(v->closeDrawer());drawer.addView(shade,new FrameLayout.LayoutParams(-1,-1));LinearLayout panel=column();panel.setBackgroundColor(CARD);panel.setElevation(d(12));panel.setClickable(true);int width=Math.min(d(340),(int)(getResources().getDisplayMetrics().widthPixels*.84));FrameLayout.LayoutParams lp=new FrameLayout.LayoutParams(width,-1,Gravity.START);drawer.addView(panel,lp);pad(panel,15,20,15,14);LinearLayout head=row();LinearLayout heading=column();add(heading,text("我的关注",26,TEXT,true));add(heading,text("选择一个网站，浏览专属信息流",12,MUTED,false));head.addView(heading,new LinearLayout.LayoutParams(0,-2,1));head.addView(action("×",false,()->closeDrawer()));add(panel,head);gap(panel,16);drawerScroll=new ScrollView(this);drawerScroll.setFillViewport(false);drawerScroll.setVerticalScrollBarEnabled(false);panel.addView(drawerScroll,new LinearLayout.LayoutParams(-1,0,1));gap(panel,12);add(panel,action("＋ 添加网站",true,()->{closeDrawer();addSource();}));gap(panel,8);add(panel,action("管理全部订阅",false,()->{closeDrawer();tab=1;render(false);}));shell.addView(drawer,new FrameLayout.LayoutParams(-1,-1));fillDrawer();panel.setTranslationX(-width);panel.animate().translationX(0).setDuration(180).start();}
    void closeDrawer(){if(drawer!=null){shell.removeView(drawer);drawer=null;drawerScroll=null;}}
    void fillDrawer(){if(drawerScroll==null)return;int y=drawerScroll.getScrollY();drawerScroll.removeAllViews();LinearLayout list=column();drawerScroll.addView(list,new ScrollView.LayoutParams(-1,-2));List<Store.Source> sources=store.sources();Map<String,Integer> unread=new HashMap<>();int total=0;for(Store.Post p:store.posts())if(!p.read){total++;unread.put(p.source,unread.getOrDefault(p.source,0)+1);}drawerRow(list,null,"全部信息",null,total);gap(list,14);add(list,text("订阅的网站 · "+sources.size(),12,MUTED,true));gap(list,7);for(Store.Source s:sources)drawerRow(list,s.id,s.name,Collector.host(s.url),unread.getOrDefault(s.id,0));drawerScroll.post(()->{if(drawerScroll!=null)drawerScroll.scrollTo(0,y);});}
    void drawerRow(LinearLayout list,String id,String name,String detail,int unread){boolean selected=Objects.equals(id,selectedSource);LinearLayout item=row();pad(item,10,10,10,10);if(selected)item.setBackground(shape(PALE,14));View icon=avatar(id,id==null?"全":name,19);item.addView(icon,new LinearLayout.LayoutParams(d(44),d(44)));LinearLayout label=column();pad(label,10,0,6,0);TextView title=text(name,15,selected?GREEN:TEXT,true);title.setMaxLines(2);title.setEllipsize(android.text.TextUtils.TruncateAt.END);add(label,title);if(detail!=null){TextView sub=text(detail,11,MUTED,false);sub.setSingleLine(true);sub.setEllipsize(android.text.TextUtils.TruncateAt.END);add(label,sub);}item.addView(label,new LinearLayout.LayoutParams(0,-2,1));if(unread>0){TextView count=text(unread>99?"99+":String.valueOf(unread),11,CARD,true);pad(count,8,4,8,4);count.setBackground(shape(GREEN,12));item.addView(count);}item.setOnClickListener(v->selectSource(id));add(list,item);gap(list,5);}
    LinearLayout card(){LinearLayout c=column();c.setBackground(outline(CARD,17,LINE));pad(c,16,15,16,15);return c;}
    void feed(){List<Store.Post> posts=store.posts();List<Store.Source> src=store.sources();if(selectedSource!=null)posts.removeIf(p->!selectedSource.equals(p.source));int unread=0;for(Store.Post p:posts)if(!p.read)unread++;
        LinearLayout controls=row(); TextView all=action("全部 "+posts.size(),!unreadOnly,()->{unreadOnly=false;render(false);});controls.addView(all);View spacer=new View(this);controls.addView(spacer,new LinearLayout.LayoutParams(d(7),1));controls.addView(action("未读 "+unread,unreadOnly,()->{unreadOnly=true;render(false);}));controls.addView(new View(this),new LinearLayout.LayoutParams(0,1,1));TextView mark=text("全部已读",12,GREEN,true);pad(mark,6,8,2,8);mark.setOnClickListener(v->{store.readSource(selectedSource);render(true);});controls.addView(mark);add(page,controls);gap(page,10);Store.Source chosen=sourceById(selectedSource);long last=chosen==null?store.lastRefresh():chosen.checked;String info=lastRunning?"正在检查订阅网站…":last>0?"上次检查 · "+format(last,"MM月dd日 HH:mm"):"等待首次更新";add(page,text(info+"   ·   "+(selectedSource==null?src.size():1)+" 个来源",12,MUTED,false));gap(page,12);
        if(src.isEmpty()){empty("还没有关注的网站","添加学校研究生院、财政厅等网站的公告列表页，新消息就会在这里出现。","添加第一个网站",()->addSource());return;}
        List<Store.Post> visible=new ArrayList<>();for(Store.Post p:posts)if(!unreadOnly||!p.read)visible.add(p);
        if(visible.isEmpty()){empty(unreadOnly?"没有未读消息":"还没有收集到信息",unreadOnly?"你已看完所有消息。":"请刷新获取公告；如果没有识别到消息，可在订阅页查看状态。",unreadOnly?"查看全部":"立即检查",()->{if(unreadOnly){unreadOnly=false;render(false);}else refresh(selectedSource);});return;}
        // Render a bounded first page, with explicit continuation to keep large feeds responsive.
        int limit=Math.min(feedLimit,visible.size());for(int n=0;n<limit;n++){Store.Post p=visible.get(n);LinearLayout c=card();LinearLayout meta=row();View icon=avatar(p.source,p.sourceName,14);icon.setOnClickListener(v->selectSource(p.source));meta.addView(icon,new LinearLayout.LayoutParams(d(34),d(34)));LinearLayout names=column();pad(names,10,0,4,0);TextView name=text(p.sourceName,13,TEXT,true);name.setMaxLines(1);name.setEllipsize(android.text.TextUtils.TruncateAt.END);add(names,name);add(names,text((p.date>0?format(p.date,p.shortPost?"yyyy-MM-dd HH:mm":"yyyy-MM-dd"):"收录于 "+format(p.found,"MM-dd HH:mm")),11,MUTED,false));meta.addView(names,new LinearLayout.LayoutParams(0,-2,1));names.setOnClickListener(v->selectSource(p.source));if(p.shortPost){TextView kind=text("动态",11,GREEN,true);pad(kind,8,3,8,3);kind.setBackground(shape(PALE,8));meta.addView(kind);View sp=new View(this);meta.addView(sp,new LinearLayout.LayoutParams(d(5),1));}if(!p.read){TextView badge=text("新",11,GREEN,true);badge.setGravity(Gravity.CENTER);pad(badge,8,3,8,3);badge.setBackground(shape(PALE,8));meta.addView(badge);}add(c,meta);gap(c,12);TextView title=text(p.title,17,p.read?0xff53635d:TEXT,true);title.setLineSpacing(d(3),1);title.setMaxLines(6);title.setEllipsize(android.text.TextUtils.TruncateAt.END);add(c,title);if(!p.summary.isEmpty()){gap(c,5);TextView desc=text(p.summary,p.shortPost?15:13,p.shortPost?TEXT:MUTED,false);desc.setLineSpacing(d(2),1);desc.setMaxLines(p.shortPost?8:3);desc.setEllipsize(android.text.TextUtils.TruncateAt.END);add(c,desc);}gap(c,11);add(c,text("查看原文  ↗",12,GREEN,true));c.setOnClickListener(v->{store.read(p.id);open(p.url);render(true);});add(page,c);gap(page,11);}if(limit<visible.size())add(page,action("加载更多",false,()->{feedLimit+=60;render(true);}));
    }
    int feedLimit=60;
    void empty(String title,String sub,String cta,Runnable click){LinearLayout c=card();pad(c,22,32,22,32);TextView icon=text("▤",38,GREEN,true);icon.setGravity(Gravity.CENTER);add(c,icon);gap(c,10);TextView a=text(title,20,TEXT,true);a.setGravity(Gravity.CENTER);add(c,a);gap(c,8);TextView b=text(sub,14,MUTED,false);b.setGravity(Gravity.CENTER);b.setLineSpacing(d(3),1);add(c,b);gap(c,20);add(c,action(cta,true,click));add(page,c);}
    void sources(){List<Store.Source> list=store.sources();if(list.isEmpty()){empty("从一个网站开始","建议复制具体栏目网址，例如官网的“招生公告”或“通知公告”列表，而不是仅复制官网首页。","＋ 添加网站",()->addSource());return;}for(Store.Source s:list){LinearLayout c=card(), header=row();View ic=avatar(s.id,s.name,15);header.addView(ic,new LinearLayout.LayoutParams(d(38),d(38)));TextView label=text(s.name,17,TEXT,true);pad(label,9,0,5,0);label.setMaxLines(2);label.setEllipsize(android.text.TextUtils.TruncateAt.END);header.addView(label,new LinearLayout.LayoutParams(0,-2,1));TextView badge=text(s.error.isEmpty()?(s.initialized?"正常":"待检查"):"异常",11,s.error.isEmpty()?GREEN:0xffac4c36,true);pad(badge,8,4,8,4);badge.setBackground(shape(s.error.isEmpty()?PALE:0xffffede7,8));header.addView(badge);header.setOnClickListener(v->selectSource(s.id));add(c,header);gap(c,7);TextView url=text(s.url,12,MUTED,false);url.setMaxLines(2);url.setEllipsize(android.text.TextUtils.TruncateAt.END);add(c,url);gap(c,7);String time=s.checked==0?"尚未检查":format(s.checked,"MM-dd HH:mm")+" 检查 · "+s.count+" 条";add(c,text(s.error.isEmpty()?time:s.error,12,s.error.isEmpty()?MUTED:0xffac4c36,false));gap(c,12);LinearLayout buttons=row();buttons.addView(action("检查",false,()->refresh(s.id)));View sp=new View(this);buttons.addView(sp,new LinearLayout.LayoutParams(d(9),1));buttons.addView(action("打开网站",false,()->open(s.url)));buttons.addView(new View(this),new LinearLayout.LayoutParams(0,1,1));TextView del=text("删除",13,0xffac4c36,true);pad(del,8,10,5,10);del.setOnClickListener(v->new AlertDialog.Builder(this).setTitle("取消订阅？").setMessage("将删除“"+s.name+"”及其已收录消息。").setNegativeButton("取消",null).setPositiveButton("删除",(dialog,w)->{store.delete(s.id);SiteIcons.remove(this,s.id);icons.remove(s.id);RefreshJob.schedule(this,true);render(false);}).show());buttons.addView(del);add(c,buttons);add(page,c);gap(page,11);}}
    void settings(){LinearLayout c=card();add(c,text("后台更新",17,TEXT,true));gap(c,7);add(c,text("手机会定期检查你的订阅。系统省电策略可能推迟后台任务。",13,MUTED,false));gap(c,14);String[] options={"15 分钟","30 分钟","1 小时","3 小时","6 小时"};int[] intervals={15,30,60,180,360};RadioGroup group=new RadioGroup(this);group.setOrientation(RadioGroup.VERTICAL);for(int i=0;i<options.length;i++){RadioButton b=new RadioButton(this);b.setId(i+101);b.setText(options[i]);b.setTextColor(TEXT);group.addView(b);if(store.interval()==intervals[i])group.check(i+101);}group.setOnCheckedChangeListener((g,id)->{store.setInterval(intervals[id-101]);RefreshJob.schedule(this,true);Toast.makeText(this,"更新频率已保存",Toast.LENGTH_SHORT).show();});add(c,group);add(page,c);gap(page,12);
        LinearLayout notify=card(), nr=row();LinearLayout nb=column();add(nb,text("新消息通知",17,TEXT,true));add(nb,text("首次导入历史公告时不通知",12,MUTED,false));nr.addView(nb,new LinearLayout.LayoutParams(0,-2,1));Switch sw=new Switch(this);sw.setChecked(store.notifyEnabled());sw.setOnCheckedChangeListener((v,b)->{store.setNotify(b);if(b)permission();});nr.addView(sw);add(notify,nr);if(Build.VERSION.SDK_INT>=33&&checkSelfPermission(Manifest.permission.POST_NOTIFICATIONS)!=PackageManager.PERMISSION_GRANTED){gap(notify,12);add(notify,text("系统通知权限尚未开启。",12,0xffac4c36,false));gap(notify,7);add(notify,action("开启系统通知",false,()->permission()));}add(page,notify);gap(page,12);LinearLayout about=card();add(about,text("关于讯集",17,TEXT,true));gap(about,8);add(about,text("版本 0.3.0 · 安卓本地版\n不需要账号或服务器。支持 RSS、静态网页公告、博客文章及常见说说动态。需要登录、动态脚本或验证码的网站暂不支持。",13,MUTED,false));add(page,about);}
    void addSource(){LinearLayout box=column();pad(box,20,6,20,4);EditText url=new EditText(this);url.setSingleLine(true);url.setInputType(android.text.InputType.TYPE_CLASS_TEXT|android.text.InputType.TYPE_TEXT_VARIATION_URI);url.setHint("https://… 网站或订阅地址");EditText name=new EditText(this);name.setSingleLine(true);name.setHint("网站名称（留空自动识别）");add(box,url);gap(box,8);add(box,name);gap(box,8);TextView tip=text("网站名称留空，将自动获取原站名称及图标。支持公告列表、博客主页、说说栏目及 RSS 地址。",12,MUTED,false);add(box,tip);AlertDialog dialog=new AlertDialog.Builder(this).setTitle("添加网站").setView(box).setNegativeButton("取消",null).setPositiveButton("添加",null).create();dialog.setOnShowListener(x->dialog.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener(v->{String u=Collector.normalize(url.getText().toString());if(u==null){url.setError("请输入有效的 http 或 https 网址");return;}String n=name.getText().toString().trim();if(n.length()>40){name.setError("名称最多 40 个字符");return;}String error=store.add(n,u);if(error!=null){url.setError(error);return;}dialog.dismiss();RefreshJob.schedule(this,true);tab=1;render(false);if(store.sources().size()==1&&store.notifyEnabled())permission();String id=null;for(Store.Source s:store.sources())if(s.url.equals(u)){id=s.id;break;}refresh(id);}));dialog.show();}
    void refresh(String id){if(store.sources().isEmpty()){addSource();return;}if(RefreshJob.running.get()){Toast.makeText(this,"正在检查，请稍候",Toast.LENGTH_SHORT).show();return;}new Thread(()->{int result=RefreshJob.refresh(getApplicationContext(),id);runOnUiThread(()->{if(isFinishing()||isDestroyed())return;render(true);if(result>=0){int errors=0;for(Store.Source s:store.sources())if(!s.error.isEmpty())errors++;Toast.makeText(this,result>0?"收到 "+result+" 条新消息":errors>0?"检查完成，部分网站存在异常":"检查完成",Toast.LENGTH_SHORT).show();}});},"xunji-manual").start();handler.postDelayed(()->render(true),160);}
    void open(String url){try{startActivity(new Intent(Intent.ACTION_VIEW,Uri.parse(url)));}catch(Exception e){Toast.makeText(this,"未找到浏览器",Toast.LENGTH_SHORT).show();}}
    void permission(){if(Build.VERSION.SDK_INT>=33&&checkSelfPermission(Manifest.permission.POST_NOTIFICATIONS)!=PackageManager.PERMISSION_GRANTED){if(store.prefs.getBoolean("permissionAsked",false)&&!shouldShowRequestPermissionRationale(Manifest.permission.POST_NOTIFICATIONS)){startActivity(new Intent(Settings.ACTION_APP_NOTIFICATION_SETTINGS).putExtra(Settings.EXTRA_APP_PACKAGE,getPackageName()));}else{store.prefs.edit().putBoolean("permissionAsked",true).apply();requestPermissions(new String[]{Manifest.permission.POST_NOTIFICATIONS},11);}}}
    String format(long date,String pattern){return new SimpleDateFormat(pattern,Locale.SIMPLIFIED_CHINESE).format(new Date(date));}
}
